import datetime
import sys
from collections import namedtuple
from contextlib import closing

# import urllib2
import requests
from pyparsing import (
    LineEnd,
    OneOrMore,
    SkipTo,
    anyCloseTag,
    anyOpenTag,
    commonHTMLEntity,
    htmlComment,
    makeHTMLTags,
    replaceHTMLEntity,
    replaceWith,
)

build_tuple = namedtuple("build_tuple", ["name", "date"])


def get_page_code(page_address, timeout=60, exit_at_error=True):
    """to be created"""
    try:
        with closing(requests.get(page_address, timeout=timeout)) as targetPage:
            targetHTML = targetPage.content.decode("UTF-8")
    except requests.exceptions.HTTPError as err:
        print("ERROR:\tProblem with address '%s': %s" % (page_address, err))
        if exit_at_error:
            sys.exit(1)
        return None
    else:
        return targetHTML


def strip_html(html_code):
    """
    htmlStripper.py
    Sample code for stripping HTML markup tags and scripts from
    HTML source files.
    Copyright (c) 2006, 2016, Paul McGuire
    """
    scriptOpen, scriptClose = makeHTMLTags("script")
    scriptBody = scriptOpen + SkipTo(scriptClose) + scriptClose
    commonHTMLEntity.setParseAction(replaceHTMLEntity)

    # first pass, strip out tags and translate entities
    firstPass = (
        (htmlComment | scriptBody | commonHTMLEntity | anyOpenTag | anyCloseTag)
        .suppress()
        .transformString(html_code)
    )

    # first pass leaves many blank lines, collapse these down
    repeatedNewlines = LineEnd() + OneOrMore(LineEnd())
    repeatedNewlines.setParseAction(replaceWith("\n\n"))
    secondPass = repeatedNewlines.transformString(firstPass)
    return secondPass


def parse_out_all_builds_from_parsed_html(parsed_html, build_re):
    """to be created"""
    _build_temp = []
    for line in parsed_html.splitlines():
        if build_re.search(line):
            build_date = build_re.search(line)
            name = build_date.group(1)[0:-1]
            date = datetime.datetime.strptime(build_date.group(2), "%d-%b-%Y %H:%M")
            _build_temp.append(build_tuple(name=name, date=date))
    return _build_temp


def parse_out_all_builds(build_address_page, build_re):
    """to be created"""
    page_code = get_page_code(build_address_page)
    parsed_html = strip_html(page_code)
    all_builds = parse_out_all_builds_from_parsed_html(parsed_html, build_re)
    return all_builds
